android.extraProguardRules:
# Keep the app's own Expo modules. Expo's default rules already keep
# module constructors and manifest components; this only pins the local
# modules so renamed classes can never break a release build.
-keep class expo.modules.keyboardmedia.** { *; }
-keep class expo.modules.systemnotifications.** { *; }
-keep class expo.modules.appupdater.** { *; }
-keep class expo.modules.devicescheme.** { *; }
-keep class expo.modules.mediathumbnails.** { *; }

# MLKit's barcode scanner is compileOnly (see
# plugins/withBarcodeScannerDisabled.js), so expo-camera's barcode paths
# reference classes that are not in the APK. Without these rules R8 fails
# the release build over them; with them, the paths stay unreachable: the
# analyzer is only created when JS asks for barcode scanning, and the
# native availability check reports the scanner as unavailable.
-dontwarn com.google.android.gms.tasks.**
-dontwarn com.google.mlkit.**
